#!/usr/bin/env bash
# V60 single-shot run on the research PC (PLAN_V60.md). Usage:  PY=/path/to/python bash run_all.sh
# Do not edit this file or any input; if a step fails, stop and return the out/ folder as it is.
set -u
cd "$(dirname "$0")"
PY=${PY:-python3}; P=16; REF_SEC=45.1
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 PYTHONHASHSEED=0
mkdir -p out
log() { echo "[$(date -u +%FT%TZ)] $*" | tee -a out/run_all.log; }
log "step 0: manifest"
sha256sum -c MANIFEST.sha256 > out/manifest_check.txt 2>&1 || { log "MANIFEST MISMATCH - stop"; exit 2; }
log "step 1: environment"
{ uname -a; lscpu; free -g; "$PY" -c "import sys, numpy, mpmath; print(sys.version); print('numpy', numpy.__version__, 'mpmath', mpmath.__version__)"; } > out/env.txt 2>&1
log "step 2: selftests"
for t in selftest_tri selftest_tri2 selftest_tri3 selftest_tri4; do
  (cd GER2 && "$PY" -I $t.py) > out/$t.log 2>&1
  grep -q "^FAILURES 0" out/$t.log || { log "$t FAILED - stop"; exit 3; }
done
log "step 3: benchmark ($P copies at once)"
for i in $(seq 1 $P); do "$PY" -I v60/bench_v60.py GER2 >> out/bench.jsonl 2>> out/bench.err & done; wait
BUDGET=$("$PY" -I -c "
import json, statistics
r = [json.loads(l)['sec'] for l in open('out/bench.jsonl')]
assert len(r) == $P, r
print(round(900*statistics.median(r)/$REF_SEC, 1))")
[ -n "$BUDGET" ] || { log "BENCHMARK FAILED - stop"; exit 4; }
log "budget per combo: $BUDGET s (= 900 x median(bench)/$REF_SEC)"
echo "$BUDGET" > out/budget_sec.txt
log "step 4: 96 combos on $P processes"
for i in $(seq 0 $((P-1))); do
  "$PY" -I v60/run_v60.py GER2 v60/samples_v60.json $i $P out/res_v60_part$i.jsonl "$BUDGET" > out/log_part$i.txt 2>&1 &
done; wait
cat out/res_v60_part*.jsonl > out/res_v60.jsonl
log "rows: $(wc -l < out/res_v60.jsonl) (expected 96)"
log "step 5: pack"
(cd out && sha256sum $(ls | grep -v -e SHA256SUMS -e run_all.log) > SHA256SUMS.txt)
tar czf V60_RESULT_$(date -u +%Y%m%d_%H%M).tar.gz out
log "done"
